def digest(raw):return 'sha256:'+hashlib.sha256(raw).hexdigest()
def encoded(value):return (json.dumps(value,indent=2,sort_keys=True)+'\n').encode()
def source_digest(raw):
    value=json.dumps(raw.decode(),ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
    return digest(value.encode())
def stable_body(value):
    r=copy.deepcopy(value);latency=r['report'].pop('route_decision_latency_ms');assert isinstance(latency,(int,float)) and latency>=0
    env=r['report']['completeness_receipt']['scope'].pop('execution_environment');assert isinstance(env,str) and env.count('/')==1 and all(env.split('/'))
    return r


def check_manifest(prefix):
    c=ROUTES[prefix]
    expected={'schema':'gooo/package-workspace-manifest/v1','entry':{'package_path':c['package'],'activity':c['activity']},'packages':[{'path':p,'sources':[PACKAGES[p]['source']]} for p in c['manifest_packages']]}
    assert json.loads((ROOT/c['workspace']).read_bytes())==expected,'wrong raw/checked manifest route: '+prefix

def check_program(prefix,p):
    c=ROUTES[prefix];assert p['schema']=='gooo/workspace-body-program/v1' and p['entry']['package_path']==c['package'] and p['entry']['activity']==c['activity'] and p['entry']['lowered_name']
    image=p['workspace_image'];assert image['schema']=='gooo/package-runtime-image/v1' and image['init_order']==c['packages']
    assert image['entry']=={'package_path':c['package'],'source':PACKAGES[c['package']]['source'],'activity':c['activity'],'inputs':['Text']*c['n'],'output':c['output']}
    assert len(image['packages'])==len(c['packages']) and {x['path'] for x in image['packages']}==set(c['packages'])
    for package in image['packages']:
        spec=PACKAGES[package['path']];sources=package['sources'];assert len(sources)==1 and sources[0]['filename']==spec['source'] and sources[0]['source_digest']==source_digest((REPO/spec['source']).read_bytes())
        exports=[{'name':name,'kind':'entity','id':eid} for name,eid in spec['entities'].items()]+[{'name':name,'kind':'activity','id':a['id'],'input_types':['gooo://std/text']*a['n'],'output_type':a['output']} for name,a in spec['activities'].items()]
        assert sorted(package['exports'],key=lambda e:e['name'])==sorted(exports,key=lambda e:e['name'])
    assert p['activities']==[p['entry']]
    if prefix=='matcher':
        assert 'pure_calls' not in p and p['entry']['lowered_name']=='GoooPackage0ActivityMatchServicePattern'
        return {(c['package'],c['activity']):p['entry']['lowered_name']}
    assert Counter((s['caller'],s['callee']) for s in p['pure_calls']['sites'])==Counter(tuple(x) for x in c['edges'])
    expected={(pkg,name) for pkg in c['packages'] for name in PACKAGES[pkg]['activities']};seen=set();lowered={}
    for a in p['pure_calls']['activities']:
        ident=a['activity'];key=(ident['package_path'],ident['activity']);assert key in expected and key not in seen;seen.add(key)
        spec=PACKAGES[key[0]];assert a['source']==spec['source'] and re.fullmatch('GoooPackage[0-9]+Activity[A-Za-z0-9]+',ident['lowered_name'])
        body=(REPO/spec['source']).read_text().split('activity '+key[1]+'(',1)[1].split('`',2)[1]
        assert a['source_body_sha256']==digest(body.encode());lowered[key]=ident['lowered_name']
    assert seen==expected and len(set(lowered.values()))==len(lowered) and lowered[(c['package'],c['activity'])]==p['entry']['lowered_name']
    return lowered

def check_body_records(prefix,report):
    expected={name:RECORDS[name] for name in ROUTES[prefix]['records']};seen=set()
    assert len(report.get('record_types',[]))==len(expected)
    for rec in report.get('record_types',[]):
        name=rec['name'];assert name in expected and name not in seen;seen.add(name);spec=expected[name]
        assert rec['id']==spec['id'] and len(rec['fields'])==len(spec['fields'])
        for actual,(fname,fid,typ) in zip(rec['fields'],spec['fields']):assert actual['name']==fname and actual['id']==fid and actual['type_id']=='urn:gooo:type:'+typ

def adapter_source(entries,validators):
    imports='\n'.join(' '+prefix.replace('-','')+' "'+MODULE+'/internal/'+prefix+'"' for prefix in ROUTES)
    calls=[]
    for prefix in ROUTES:
        if prefix=='conditional-apply':
            calls.append('func nativeGrantUpdate(f GrantUpdateFacts) any { return conditionalapply.'+entries[prefix]+'(f.Before,f.After,f.RequiredType,f.RequiredName) }');continue
        kind=prefix.removeprefix('checked-');facts=kind.title()+'Facts';args={'matcher':'f.Pattern,f.ReqType,f.ReqName','impact':'f.Before,f.After,f.ReqType,f.ReqName','refinement':'f.Before,f.After'}[kind]
        name='native'+kind.title()+('Checked' if prefix.startswith('checked-') else '');out='bool' if prefix=='matcher' else 'any'
        calls.append('func '+name+'(f '+facts+') '+out+' { return '+prefix.replace('-','')+'.'+entries[prefix]+'('+args+') }')
    for kind in ['Type','Name','Pattern']:calls.append('func nativeValid'+kind+'(value string) bool { return checkedmatcher.'+validators['ValidateService'+kind]+'(value) }')
    return '// Code generated from pinned compiler-owned entry identities; DO NOT EDIT.\npackage servicepolicy\nimport (\n'+imports+'\n)\n'+'\n'.join(calls)+'\n'

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--compiler',type=Path,required=True);ap.add_argument('--go',type=Path,required=True);ap.add_argument('--out',type=Path,default=ROOT/'out/generation');ap.add_argument('--check',action='store_true');args=ap.parse_args()
    args.compiler=args.compiler.resolve();args.go=args.go.resolve();out=args.out.resolve();out.mkdir(parents=True,exist_ok=True);out.chmod(0o700)
    env=os.environ.copy();env.update(GOTOOLCHAIN='local',GOWORK='off',GOPROXY='off',GOSUMDB='off')
    def run(label,cmd,data=None,cwd=ROOT):
        r=subprocess.run([str(x) for x in cmd],input=data,cwd=cwd,env=env,capture_output=True,timeout=60)
        for stream,raw in [('stdout',r.stdout),('stderr',r.stderr)]:p=out/(label+'.'+stream);p.write_bytes(raw);p.chmod(0o600)
        if r.returncode!=0:raise RuntimeError(label+' failed; inspect retained private output')
        return r.stdout
    version=run('go-version',[args.go,'version']).decode().split();assert version[:3]==['go','version','go1.27.3'] and len(version)==4
    compiler_raw=run('compiler-identity',[args.compiler,'version','--build','--json']);identity=json.loads(compiler_raw)
    assert identity['compiler_source_sha']==identity['vcs_revision']==PIN and identity['source_status']=='CLEAN_VCS' and identity['vcs_modified']=='false' and identity['go_version']==identity['native_go_required']=='go1.27.3'
    for mirror,canonical in CANONICAL.items():assert (ROOT/mirror).read_bytes()==(REPO/canonical).read_bytes(),'canonical source/workspace mirror diverged: '+mirror
    for prefix in ROUTES:check_manifest(prefix)
    adaptation=json.loads((REPO/'upstream.json').read_bytes())['bounded_agentmesh_adaptations'];assert len(adaptation)==1 and encoded(adaptation[0])==(ROOT/'evidence/repository-adaptation.json').read_bytes()
    produced={'compiler.json':compiler_raw,**{mirror:(ROOT/source).read_bytes() for mirror,source in MIRRORS.items()}};entries={};validators={}
    with tempfile.TemporaryDirectory(prefix='gooo-agentmesh-lowering-') as tmp:
        for prefix,c in ROUTES.items():
            workspace=c['canonical_workspace'];casepath=ROOT/'receipts'/(prefix+'-seed-cases.json');rows=json.loads(casepath.read_bytes())['cases']
            raw=run(prefix+'-execute',[args.compiler,'package','execute','--json','--cases',casepath,'--go',args.go,workspace],cwd=REPO);receipt=json.loads(raw)
            assert receipt['schema']=='gooo/workspace-body-execution-receipt/v1' and receipt['decision']=='PASS' and receipt['manifest_digest']==digest((REPO/workspace).read_bytes()) and receipt['cases_digest']==digest(casepath.read_bytes())
            p=receipt['result']['program'];lowered_names=check_program(prefix,p)
            if prefix=='checked-matcher':validators={name:lowered_names[('gooo/service-domain',name)] for name in PACKAGES['gooo/service-domain']['activities']}
            rt=receipt['result']['runtime'];assert rt['producer_source_sha']==PIN and rt['go_version'].split()[:3]==['go','version','go1.27.3'] and rt['projection_replayed'] and rt['runtime_replayed'] and rt['finite_passed']==rt['finite_total']==len(rows)
            replay=json.loads(run(prefix+'-replay',[args.compiler,'package','replay','--json','--receipt',out/(prefix+'-execute.stdout'),'--cases',casepath,'--go',args.go,workspace],cwd=REPO))
            assert replay['decision']=='PASS' and replay['replayed_from_sha256']==digest(raw) and replay['result']['program']==p and replay['result']['runtime']['finite_passed']==len(rows)
            lowered=p['lowered_gooo_source'].encode();lowerfile=Path(tmp)/(prefix+'.gooo');lowerfile.write_bytes(lowered)
            bodyraw=run(prefix+'-body-codegen',[args.compiler,'body-codegen','--json','--activity',p['entry']['lowered_name'],lowerfile]);body=json.loads(bodyraw);report=body['report']
            input_type='('+','.join(['string']*c['n'])+')'
            assert report['schema']=='gooo/body-codegen-report/v3' and report['decision']=='PASS' and report['activity']==p['entry']['lowered_name'] and report['activity_id']==c['id'] and report['input_type']==input_type and report['output_type']==c['go_output']
            assert report['compiler_source_sha']==PIN and report['source_digest']==digest(lowered) and report['generated_digest']==report['replay_digest']==digest(body['source'].encode()) and report['typecheck_passed'] and report['deterministic_replay'] and report['repository_writes']==0
            check_body_records(prefix,report)
            public_body=ROOT/'receipts'/(prefix+'-body-codegen.json')
            if public_body.exists() and stable_body(json.loads(public_body.read_bytes()))==stable_body(body):bodyraw=public_body.read_bytes()
            produced['receipts/'+prefix+'-program.json']=encoded(p);produced['receipts/'+prefix+'-lowered.gooo']=lowered;produced['receipts/'+prefix+'-body-codegen.json']=bodyraw
            produced['internal/'+prefix+'/generated.go']=run(prefix+'-gofmt',[args.go.parent/'gofmt'],body['source'].encode());entries[prefix]=p['entry']['lowered_name']
            if args.check:assert stable_body(json.loads(public_body.read_bytes()))==stable_body(body)
    produced['adapter_generated.go']=run('adapter-gofmt',[args.go.parent/'gofmt'],adapter_source(entries,validators).encode())
    if args.check:
        for name,raw in produced.items():
            if name.endswith('-body-codegen.json'):continue
            assert (ROOT/name).read_bytes()==raw,name+' differs from compiler-owned route'
        g=json.loads((ROOT/'generation.json').read_bytes());assert g['schema']=='gooo/agentmesh-native-generation/v1' and g['origin']=='fresh_pinned_generation' and g['assets']=={name:digest((ROOT/name).read_bytes()) for name in FILES} and g['public_sources']=={canonical:digest((REPO/canonical).read_bytes()) for canonical in PUBLIC_SOURCES}
        print('PASS: checked defaults and raw compatibility freshly executed/replayed with exact sources, exports, fields, calls and generated validator adapters')
    else:
        for name,raw in produced.items():(ROOT/name).write_bytes(raw)
        (ROOT/'generation.json').write_bytes(encoded({'schema':'gooo/agentmesh-native-generation/v1','origin':'fresh_pinned_generation','public_sources':{canonical:digest((REPO/canonical).read_bytes()) for canonical in PUBLIC_SOURCES},'assets':{name:digest((ROOT/name).read_bytes()) for name in FILES}}))
        print('PASS: fresh pinned checked-default and raw-compatibility projections generated; finite acceptance remains separate')
if __name__=='__main__':main()
